package com.cnpm.clothingstore.repository;

import com.cnpm.clothingstore.entity.Product; import org.springframework.data.jpa.repository.*; import org.springframework.data.domain.*; import org.springframework.data.repository.query.Param; import jakarta.persistence.LockModeType; import java.util.*; import java.math.*;

public interface ProductRepository extends JpaRepository<Product,Long>, JpaSpecificationExecutor<Product> {
    Page<Product> findByNameContainingIgnoreCaseAndActiveTrue(String n,Pageable p);
    Optional<Product> findByIdAndActiveTrue(Long id); long countByActiveTrue();
    @Query("select p from Product p where p.active=true and (:keyword='' or lower(p.name) like lower(concat('%',:keyword,'%')) or lower(p.categoryEntity.name) like lower(concat('%',:keyword,'%'))) and (:category='' or p.categoryEntity.name=:category) and (:subCategory='' or (:subCategory='JEANS' and (lower(p.name) like '%jean%' or lower(p.name) like '%denim%') and lower(p.name) not like '%short%') or (:subCategory='SHORT' and lower(p.name) like '%short%' and lower(p.name) not like '%boxer%') or (:subCategory='KAKI_CHINO' and (lower(p.name) like '%kaki%' or lower(p.name) like '%chino%') and lower(p.name) not like '%short%') or (:subCategory='JOGGER_LONG' and (lower(p.name) like '%jogger%' or lower(p.name) like '%quần dài%' or lower(p.name) like '%quần dù%') and lower(p.name) not like '%short%') or (:subCategory='TROUSERS' and (lower(p.name) like '%quần tây%' or lower(p.name) like '%trousers%') and lower(p.name) not like '%short%') or (:subCategory='BOXER' and (lower(p.name) like '%boxer%' or lower(p.name) like '%trunks%')) or (:subCategory='CARGO' and lower(p.name) like '%cargo%' and lower(p.name) not like '%short%' and lower(p.name) not like '%jogger%')) and (:gender='' or p.gender=:gender) and (:minPrice is null or coalesce(p.salePrice,p.price)>=:minPrice) and (:maxPrice is null or coalesce(p.salePrice,p.price)<=:maxPrice) and (:onSale = false or (p.salePrice is not null and p.salePrice > 0 and p.salePrice < p.price))")
    Page<Product> searchCatalogFiltered(@Param("keyword") String keyword,@Param("category") String category,@Param("subCategory") String subCategory,@Param("gender") String gender,@Param("minPrice") BigDecimal minPrice,@Param("maxPrice") BigDecimal maxPrice,@Param("onSale") boolean onSale,Pageable pageable);
    default Page<Product> searchCatalog(String keyword,String category,String gender,BigDecimal minPrice,BigDecimal maxPrice,Pageable pageable){return searchCatalogFiltered(keyword,category,"",gender,minPrice,maxPrice,false,pageable);}
    @Query("select distinct p.categoryEntity.name from Product p where p.active=true and p.categoryEntity is not null order by p.categoryEntity.name") List<String> findActiveCategories();
    @Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select p from Product p where p.id=:id") Optional<Product> findLockedById(@Param("id") Long id);
}
